"""Storage budgets cover imports and generated bytes without removing sources."""

import hashlib
import os
import subprocess
import time
from pathlib import Path

import pytest
from fastapi.testclient import TestClient

from tuber_studio.app import create_app
from tuber_studio.infra.media.cache import MIB, CachePolicy

FIXTURE = Path(__file__).resolve().parents[1] / "fixtures/audio/tone.flac"


def put(directory, name, size):
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / name
    with path.open("wb") as output:
        output.truncate(size)
    return path


async def test_music_import_and_online_share_one_budget_and_catalog_is_protected(runtime):
    cache = runtime.cache
    data = FIXTURE.read_bytes()
    identity = hashlib.sha256(data).hexdigest()
    path = runtime.live.media.directory / (identity + ".flac")
    path.write_bytes(data)
    song = await runtime.live.media.save_song(
        {"id": "own", "title": "自有素材", "audio": identity, "license_note": "generated"}
    )
    spare = put(runtime.live.online_songs.directory, "f" * 64 + ".mp3", 1000)
    assert cache.status()["categories"]["music"]["bytes"] == len(data) + 1000
    result = await cache.clear("music")
    assert path.exists() and not spare.exists() and result["freed_bytes"] == 1000
    runtime.store.set("music_catalog", [])
    await cache.clear("music")
    assert not path.exists() and song["audio"] == identity


async def test_speech_lru_budget_is_enforced_before_writing(runtime):
    old = put(runtime.settings.audio, "a" * 64 + ".wav", 12 * MIB)
    recent = put(runtime.settings.audio, "b" * 64 + ".wav", 6 * MIB)
    os.utime(old, (1, 1))
    await runtime.cache.configure({"speech_limit_mib": 16})
    assert not old.exists() and recent.exists()
    runtime.cache.touch(recent, seconds=180)
    async with runtime.cache.write("speech", 12 * MIB) as allowed:
        assert allowed == 10 * MIB
    assert recent.exists()


async def test_cleanup_skips_uploads_active_audio_and_never_touches_models(runtime):
    upload = put(runtime.live.media.directory, "a" * 64 + ".mp3", 100)
    runtime.cache.touch(upload, seconds=300)
    model = put(runtime.settings.runtime / "models", "a" * 64 + ".mp3", 200)
    temporary = put(runtime.settings.runtime / "singing/output/job", "work.wav", 300)
    runtime.cache.writing.add("temporary")
    assert (await runtime.cache.clear("music"))["removed_files"] == 0
    assert (await runtime.cache.clear("temporary"))["removed_files"] == 0
    runtime.cache.writing.clear()
    assert (await runtime.cache.clear("temporary"))["freed_bytes"] == 300
    assert model.exists() and upload.exists() and not temporary.exists()


async def test_lower_limit_does_not_delete_or_commit_below_protected_sources(runtime):
    path = put(runtime.settings.audio, "a" * 64 + ".wav", 17 * MIB)
    runtime.cache.touch(path, seconds=180)
    previous = runtime.cache.policy()
    with pytest.raises(ValueError, match="受保护"):
        await runtime.cache.configure({"speech_limit_mib": 16})
    assert runtime.cache.policy() == previous and path.exists()


def test_cache_api_scopes_shared_setting_and_music_hard_max(settings):
    app = create_app(settings)
    with TestClient(app) as client:
        assert client.get("/api/v1/system/cache").status_code == 401
        client.post("/api/v1/system/auth/overlay", json={"token": settings.overlay_token})
        assert client.get("/api/v1/system/cache").status_code == 401
        client.post("/api/v1/system/auth/login", json={"token": settings.admin_token})
        assert client.get("/api/v1/system/cache").json()["settings"]["music_limit_mib"] == 15360
        assert client.put("/api/v1/system/cache", json={"music_limit_mib": 15361}).status_code == 422
        assert client.put("/api/v1/system/cache", json={"music_limit_mib": 1024}).status_code == 200
        assert client.get("/api/v1/live/online").json()["settings"]["cache_limit_mib"] == 1024
        assert client.post("/api/v1/system/cache/not-a-directory/clear").status_code == 400
        assert CachePolicy().music_limit_mib * MIB == 15 * 1024**3


def test_music_lru_access_preserves_etag_and_conditional_ranges(settings):
    with TestClient(create_app(settings)) as client:
        client.post("/api/v1/system/auth/login", json={"token": settings.admin_token})
        data = FIXTURE.read_bytes()
        uploaded = client.post("/api/v1/live/uploads", content=data).json()
        url = "/media/music/" + uploaded["id"]
        first = client.get(url)
        second = client.get(url, headers={"Range": "bytes=0-31", "If-Range": first.headers["etag"]})
        assert second.status_code == 206 and second.content == data[:32]
        assert second.headers["etag"] == first.headers["etag"]


def test_status_streams_current_protection_without_reading_lru(runtime):
    music = put(runtime.live.online_songs.directory, "c" * 64 + ".flac", 17)
    put(runtime.settings.audio, "a" * 64 + ".wav", 11)
    put(runtime.settings.runtime / "singing/output/job/nested", "arbitrary.work", 31)
    runtime.cache.leases[str(music)] = time.monotonic() + 60
    runtime.store.execute("INSERT INTO media_cache_access VALUES('unmanaged/missing.wav',0)")
    statements = []
    runtime.store.db.set_trace_callback(statements.append)
    try:
        first = runtime.cache.status()
        runtime.cache.leases[str(music)] = time.monotonic() - 1
        music.write_bytes(b"x" * 23)
        second = runtime.cache.usage("music")
    finally:
        runtime.store.db.set_trace_callback(None)
    assert first["categories"]["music"]["protected_bytes"] == 17
    assert second["protected_bytes"] == 0 and second["reclaimable_bytes"] == 23
    assert first["categories"]["speech"]["bytes"] == 11
    assert first["categories"]["temporary"]["bytes"] == 31
    assert not any("media_cache_access" in statement.lower() for statement in statements)


async def test_lru_uses_touch_after_status_not_just_modification_time(runtime):
    older = put(runtime.settings.audio, "a" * 64 + ".wav", 9 * MIB)
    newer = put(runtime.settings.audio, "b" * 64 + ".wav", 9 * MIB)
    os.utime(older, (1, 1))
    os.utime(newer, (2, 2))
    runtime.cache.status()
    runtime.cache.touch(older)
    await runtime.cache.configure({"speech_limit_mib": 16})
    assert older.exists() and not newer.exists()


def test_only_temporary_pool_recurses_and_arbitrary_source_names_are_ignored(runtime):
    root = runtime.settings.runtime
    put(runtime.live.online_songs.directory / "nested", "a" * 64 + ".wav", 13)
    put(runtime.live.online_songs.directory, "source-original.wav", 19)
    put(root / "singing/output/a/b/c", "source-original.wav", 23)
    assert runtime.cache.usage("music")["files"] == 0
    assert runtime.cache.usage("temporary")["bytes"] == 23


@pytest.fixture
def directory_link():
    links = []

    def create(link, target):
        link.parent.mkdir(parents=True, exist_ok=True)
        try:
            link.symlink_to(target, target_is_directory=True)
        except (OSError, NotImplementedError):
            if os.name != "nt":
                pytest.skip("Directory symlink unavailable")
            # Junctions need no Developer Mode/admin privilege and exercise the
            # Windows boundary. Removing the link below never traverses its target.
            result = subprocess.run(
                ["cmd", "/c", "mklink", "/J", str(link), str(target)],
                capture_output=True,
                creationflags=subprocess.CREATE_NO_WINDOW,
            )
            if result.returncode:
                pytest.skip("Directory symlink/junction unavailable")
        links.append(link)

    yield create
    for link in links:
        if link.is_symlink():
            link.unlink()
        else:
            link.rmdir()


@pytest.mark.parametrize("placement", ["root", "unrecognized_entry", "nested_temporary"])
def test_directory_links_are_rejected_before_following_or_filtering(runtime, directory_link, placement):
    root = runtime.settings.runtime
    sentinel = put(root / "unmanaged", "a" * 64 + ".wav", 29)
    if placement == "root":
        link = runtime.live.online_songs.directory
        link.rmdir()
        category = "music"
    elif placement == "unrecognized_entry":
        link, category = runtime.live.online_songs.directory / "not-a-cache-file", "music"
    else:
        link, category = root / "singing/output/job/deep/alias", "temporary"
    directory_link(link, sentinel.parent)
    with pytest.raises(ValueError, match="不能使用链接"):
        runtime.cache.usage(category)
    with pytest.raises(ValueError, match="不能使用链接"):
        runtime.cache.enforce(category, clear=True)
    assert sentinel.exists() and sentinel.stat().st_size == 29


async def test_video_renders_atomic_lru_protection_and_preserves_job_rows(runtime, directory_link):
    root = runtime.settings.runtime
    renders = root / "video_renders"
    j1 = put(renders / "rem_old", "output.mp4", 8 * MIB)
    put(renders / "rem_old" / "public", "narration.wav", 4 * MIB)
    j2 = put(renders / "rem_mid", "output.mp4", 8 * MIB)
    j3_active = put(renders / "rem_active", "output.mp4", 60 * MIB)
    os.utime(j1, (10, 10))
    os.utime(j2, (20, 20))

    now = time.time()
    with runtime.store.db:
        runtime.store.db.executemany(
            "INSERT INTO remotion_video_jobs(id,status,plan_json,created_at,updated_at) VALUES(?,?,?,?,?)",
            [
                ("rem_old", "published", "{}", now, now),
                ("rem_mid", "ready_for_review", "{}", now, now),
                ("rem_active", "rendering", "{}", now, now),
            ],
        )

    runtime.cache.touch(j2.parent)
    status = runtime.cache.status()
    assert status["categories"]["video"]["protected_bytes"] == 60 * MIB
    assert status["categories"]["video"]["reclaimable_bytes"] == 20 * MIB
    assert status["summary"]["bytes"] >= 80 * MIB

    # Protected rendering job (60 MiB) > 64 MiB fails? Wait: 60 MiB < 64 MiB -> lowering to 64 MiB evicts LRU rem_old + rem_mid?
    # Let's test setting video_limit_mib to 70 MiB -> rem_old (12 MiB) evicted, rem_mid (8 MiB) & rem_active (60 MiB) kept (total 68 MiB <= 70 MiB).
    await runtime.cache.configure({"video_limit_mib": 70, "speech_limit_mib": 320})
    assert not (renders / "rem_old").exists()
    assert (renders / "rem_mid").exists()
    assert j3_active.exists()
    # Partial configure preserves video_limit_mib when only speech_limit_mib is updated later:
    await runtime.cache.configure({"speech_limit_mib": 256})
    assert runtime.cache.policy()["video_limit_mib"] == 70
    assert runtime.cache.policy()["speech_limit_mib"] == 256
    # SQLite job row & receipt metadata stay intact after cache eviction:
    assert runtime.store.one("SELECT status FROM remotion_video_jobs WHERE id='rem_old'")["status"] == "published"

    # Clear video removes remaining reclaimable job dirs while protecting rendering job:
    res = await runtime.cache.clear("video")
    assert not (renders / "rem_mid").exists()
    assert j3_active.exists() and res["freed_bytes"] == 8 * MIB

    # Symlink rejection inside video_renders:
    sentinel = put(root / "unmanaged_vid", "secret.mp4", 42)
    directory_link(renders / "rem_link", sentinel.parent)
    with pytest.raises(ValueError, match="不能使用链接"):
        runtime.cache.usage("video")


async def test_browsing_clips_and_assets_preview_cleanup_and_clear_all(settings, runtime, directory_link):
    root = runtime.settings.runtime
    clip = put(root / "browsing/private-clips", "12345678-1234-5678-1234-567812345678.mp4", 2048)
    preview = put(root / "private-call-previews/whale", "mature.mp4", 4096)
    speech = put(runtime.settings.audio, "c" * 64 + ".wav", 1024)
    # Durable assets that MUST NEVER be touched by clear_all:
    model = put(root / "models", "weights.bin", 512)
    meme_lib = put(root / "memes", "a" * 64 + ".png", 256)
    art_ref = put(root / "private-artifacts/artwork-references/whale/q", "ref.png", 128)

    status = runtime.cache.status()
    assert status["categories"]["browsing"]["bytes"] == 2048
    assert status["categories"]["assets"]["bytes"] == 4096
    assert status["summary"]["reclaimable_bytes"] == 2048 + 4096 + 1024

    cleared = await runtime.cache.clear_all()
    assert cleared["freed_bytes"] == 2048 + 4096 + 1024
    assert not clip.exists() and not preview.exists() and not speech.exists()
    assert model.exists() and meme_lib.exists() and art_ref.exists()

    # HTTP API smoke for 7-category cache & clear-all:
    with TestClient(create_app(settings)) as client:
        client.post("/api/v1/system/auth/login", json={"token": settings.admin_token})
        got = client.get("/api/v1/system/cache").json()
        assert set(got["categories"]) == {"video", "music", "speech", "browsing", "temporary", "assets", "meme_inbox"}
        assert "summary" in got
        put_res = client.put("/api/v1/system/cache", json={"video_limit_mib": 2048, "assets_limit_mib": 256})
        assert put_res.status_code == 200
        assert put_res.json()["settings"]["video_limit_mib"] == 2048
        assert put_res.json()["settings"]["assets_limit_mib"] == 256
        clear_all_res = client.post("/api/v1/system/cache/clear-all")
        assert clear_all_res.status_code == 200 and "result" in clear_all_res.json()

    # Symlink rejection inside private-call-previews:
    sentinel = put(root / "unmanaged_asset", "keep.mp4", 64)
    directory_link(root / "private-call-previews/link", sentinel.parent)
    with pytest.raises(ValueError, match="不能使用链接"):
        runtime.cache.usage("assets")
